import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong(), b = sc.nextLong();
        // Repeated subtraction keeps the gcd; taking remainders batches those subtractions.
        while (b != 0) {
            long r = a % b;
            a = b;
            b = r;
        }
        System.out.println(a);
    }
}

